#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    // Expect exactly two arguments (program name + two strings)
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    // Length limit: strings must be shorter than 1025 characters
    if (strlen(argv[1]) >= 1025 || strlen(argv[2]) >= 1025) {
        puts("TOO_LONG");
        return 0;
    }

    // Frequency tables for each string (case‑insensitive, ignore spaces)
    int freq1[256] = {0};
    int freq2[256] = {0};

    for (const char *p = argv[1]; *p; ++p) {
        if (*p == ' ') continue;                 // ignore spaces
        if (isalpha((unsigned char)*p)) {
            unsigned char c = (unsigned char)tolower((unsigned char)*p);
            freq1[c]++;
        }
    }
    for (const char *p = argv[2]; *p; ++p) {
        if (*p == ' ') continue;                 // ignore spaces
        if (isalpha((unsigned char)*p)) {
            unsigned char c = (unsigned char)tolower((unsigned char)*p);
            freq2[c]++;
        }
    }

    // Compare the two frequency tables
    int not_anagram = 0;
    for (int i = 0; i < 256; ++i) {
        if (freq1[i] != freq2[i]) {
            not_anagram = 1;
            break;
        }
    }

    puts(not_anagram ? "NOT_ANAGRAM" : "ANAGRAM");
    return 0;
}
